/* Core keeps legacy objects intact; stable IDs link their new counterparts. */
if (!state.coreVersion) {
  localStorage.setItem('deutsch-os-before-core', JSON.stringify(state));
  state.sources = state.materials.map(m => ({...m, text: '', position: ''}));
  state.sessions = state.tasks.map(t => ({id:t.id, sourceId:t.materialId||null,
    date:t.date, title:taskTitle(t), status:t.completed?'completed':'planned',
    minutes:t.log?.minutes||t.minutes, focus:t.log?.focus||[], position:t.log?.position||'',
    confidence:t.log?.confidence||'', note:t.log?.note||t.note||'', updatedAt:0}));
  state.artifacts = state.notes.map(n => ({...n, sessionId:n.taskId||null}));
  state.coreVersion=1;
  save();
}
if (!state.settings) state.settings={level:'A1',days:'4',minutes:'20',preference:'混合',focus:'平衡',deadline:''};
document.querySelector('#setup').style.display='none';
let activeSessionId=null;
const $=id=>document.getElementById(id);
const coreSave=()=>save();
const builtinPlanSources=[
 {id:'builtin-nicos-a1',title:'Nicos Weg · A1',url:'https://learngerman.dw.com/en/nicos-weg/c-36519789',type:'视频课程'},
 {id:'builtin-news',title:'Nachrichtenleicht · 简易德语新闻',url:'https://www.nachrichtenleicht.de/',type:'文章'},
 {id:'builtin-podcast',title:'Easy German Podcast',url:'https://www.easygerman.fm/',type:'播客'}
];
const coreSource=id=>state.sources.find(s=>s.id===id)||builtinPlanSources.find(s=>s.id===id);
const safeURL=value=>{try {const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const coreStyle=document.createElement('style');
coreStyle.textContent=`.core-actions{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.core-row{padding:18px 0;border-bottom:1px solid var(--line)}.core-row p{white-space:pre-wrap;overflow-wrap:anywhere}.core-reader{white-space:pre-wrap;line-height:1.9;max-height:35vh;overflow:auto;padding:16px;background:white;border:1px solid var(--line);border-radius:10px}.core-meta{font-size:12px;color:var(--muted);margin:8px 0}.core-actions button,.core-actions a{min-height:44px}.form-grid .focus-option input{width:16px;flex:0 0 16px;margin:0}.core-row h2{font-size:17px;margin:0}.core-row a{overflow-wrap:anywhere}.bottom-nav button{flex:1}.core-hint{font-size:12px;color:var(--muted)}@media(max-width:760px){.modal{padding:18px}.core-actions>*{flex:1}.core-reader{max-height:30dvh}}`;
document.head.append(coreStyle);
const nav=[['today','今天'],['materials','来源'],['notes','记录'],['review','复习']];
document.querySelector('.nav').innerHTML=nav.map(([id,label])=>`<button onclick="showPage('${id}')" data-page="${id}">${label}</button>`).join('')+`<div class="nav-label">可选工具</div><button onclick="showPage('plan')">旧版计划</button><button onclick="showPage('settings')">设置与备份</button>`;
document.querySelector('.bottom-nav').innerHTML=nav.map(([id,label])=>`<button onclick="showPage('${id}')" data-page="${id}">${label}</button>`).join('');
$('materials').innerHTML=`<h1 class="headline">来源</h1><p class="sub">一篇文章、一个链接，或者一本书的学习位置。</p><div class="toolbar"><input id="sourceSearch" class="search" placeholder="搜索来源" oninput="renderSources()"><button class="primary" onclick="addSource()">添加来源</button></div><div id="sourceList" class="card"></div>`;
$('notes').innerHTML=`<h1 class="headline">学习记录</h1><p class="sub">课程位置、练习重点、感受和笔记都留在这里。</p><div class="toolbar"><input id="recordSearch" class="search" placeholder="搜索课程、笔记、词汇…" oninput="renderRecords()"><button class="secondary" onclick="exportCoreMarkdown()">导出 Markdown</button></div><div id="recordList" class="card"></div>`;
function sourceRow(s){return `<article class="core-row"><h2>${esc(s.title)}</h2><p class="core-meta">${esc(s.type)}${s.position?' · 上次：'+esc(s.position):''}</p><div class="core-actions"><button class="secondary" onclick="startSession('${s.id}')">开始学习</button>${safeURL(s.url)?`<a class="ghost" href="${esc(safeURL(s.url))}" target="_blank" rel="noopener">打开原材料 ↗</a>`:''}</div></article>`}
function renderSources(){const q=($('sourceSearch')?.value||'').toLowerCase();$('sourceList').innerHTML=state.sources.filter(s=>(s.title+' '+s.text).toLowerCase().includes(q)).map(sourceRow).join('')||'<p class="empty">粘贴一篇文章，或保存你在用的材料链接。</p>'}
function addSource(){activeSessionId=null; $('modalContent').innerHTML=`<h2>添加来源</h2><p class="sub">只填标题也可以开始；正文和链接都可选。</p><form onsubmit="saveSource(event)"><div class="form-grid"><label class="full">标题<input id="sourceTitle" required maxlength="200"></label><label>类型<select id="sourceType"><option>文章</option><option>教材</option><option>音频</option><option>视频</option><option>词书</option><option>自由练习</option></select></label><label>链接（可选）<input id="sourceURL" type="url" placeholder="https://"></label><label class="full">正文（可选）<textarea id="sourceText" rows="7" placeholder="贴入你要阅读的文本"></textarea></label></div><div class="modal-foot"><button type="button" class="ghost" onclick="closeModal()">取消</button><button class="primary">保存并开始学习</button></div></form>`;openModal()}
function saveSource(e){e.preventDefault();const url=$('sourceURL').value.trim();if(url&&!safeURL(url)){ $('sourceURL').setCustomValidity('请使用 http 或 https 链接');$('sourceURL').reportValidity();$('sourceURL').oninput=()=> $('sourceURL').setCustomValidity('');return}const s={id:uid(),title:$('sourceTitle').value.trim(),type:$('sourceType').value,url,text:$('sourceText').value,position:''};if(!s.title)return;state.sources.unshift(s);coreSave();startSession(s.id)}
function startSession(sourceId=null){persistSession();const s=coreSource(sourceId);let session=state.sessions.find(x=>x.sourceId===sourceId&&x.status==='active');if(!session){session={id:uid(),sourceId,date:todayKey(),title:s?.title||'自由学习',status:'active',minutes:20,focus:[],position:s?.position||'',confidence:'刚接触',note:'',updatedAt:Date.now()};state.sessions.unshift(session)}coreSave();openSession(session.id)}
function openSession(id){activeSessionId=id;const r=state.sessions.find(s=>s.id===id),s=coreSource(r.sourceId);$('modalContent').innerHTML=`<h2>${esc(r.title)}</h2><p class="sub">记录会自动保存，可以随时回来继续。</p>${safeURL(s?.url)?`<div class="core-actions"><a class="primary" target="_blank" rel="noopener" href="${esc(safeURL(s.url))}">打开学习材料 ↗</a></div>`:''}${s?.text?`<div class="core-reader">${esc(s.text)}</div>`:''}<div class="form-grid" oninput="persistSession()" onchange="persistSession()"><label>学习日期<input id="sessionDate" type="date" value="${esc(r.date)}"></label><label>实际用时（分钟）<input id="sessionMinutes" type="number" min="0" max="1440" value="${r.minutes}"></label><label class="full">学到哪里了？<input id="sessionPosition" value="${esc(r.position)}" placeholder="A1 第 3 课 / 第 2 段 / 04:12"></label><div class="full">这次主要练了什么？<div class="focus-grid">${['词汇','语法','听力','口语','阅读','写作'].map(f=>`<label class="focus-option"><input name="sessionFocus" type="checkbox" value="${f}" ${r.focus.includes(f)?'checked':''}>${f}</label>`).join('')}</div></div><label class="full">完成感受<select id="sessionConfidence">${['刚接触','基本理解','可以应用'].map(x=>`<option ${r.confidence===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="full">笔记（可以留空）<textarea id="sessionNote" rows="5">${esc(r.note)}</textarea></label></div><p class="core-hint">留下一句下次想再看的内容，就给复习留了一条线索。</p><div class="modal-foot"><button class="ghost" onclick="closeModal()">保存并关闭</button><button class="primary" onclick="finishSession()">${r.status==='completed'?'保存修改':'结束学习'}</button></div>`;openModal()}
function persistSession(){if(!activeSessionId||!$('sessionNote'))return;const r=state.sessions.find(s=>s.id===activeSessionId);r.note=$('sessionNote').value;r.position=$('sessionPosition').value;r.date=$('sessionDate').value||todayKey();r.minutes=Math.min(1440,Math.max(0,Number($('sessionMinutes').value)||0));r.focus=[...document.querySelectorAll('[name=sessionFocus]:checked')].map(x=>x.value);r.confidence=$('sessionConfidence').value;r.updatedAt=Date.now();const source=coreSource(r.sourceId);if(source)source.position=r.position;coreSave()}
function finishSession(){persistSession();const r=state.sessions.find(s=>s.id===activeSessionId);r.status='completed';if(r.note.trim()){let a=state.artifacts.find(x=>x.sessionId===r.id);const source=coreSource(r.sourceId);if(!a){a={id:uid(),sessionId:r.id};state.artifacts.unshift(a)}Object.assign(a,{text:r.note,date:r.date,minutes:r.minutes,materialTitle:r.title,url:source?.url||'',summary:r.position});}coreSave();closeModal();renderAll()}
const legacyClose=closeModal;
closeModal=function(){persistSession();activeSessionId=null;legacyClose();renderAll()};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
window.addEventListener('pagehide',persistSession);
function renderRecords(){const q=($('recordSearch')?.value||'').toLowerCase();const rows=state.sessions.filter(r=>r.status==='completed'&&(r.title+' '+r.note+' '+r.position+' '+r.focus.join(' ')).toLowerCase().includes(q));$('recordList').innerHTML=rows.map(r=>`<article class="core-row"><h2>${esc(r.title)}</h2><p class="core-meta">${esc(r.date)} · ${r.minutes} 分钟 · ${esc(r.focus.join(' / '))}</p><p class="core-meta">${esc(r.position)} ${esc(r.confidence)}</p>${r.note?`<p>${esc(r.note)}</p>`:''}<div class="core-actions"><button class="ghost" onclick="openSession('${r.id}')">查看 / 编辑</button>${r.note?`<button class="ghost" onclick="reviewSession('${r.id}')">加入复习</button>`:''}</div></article>`).join('')||'<p class="empty">结束一次学习后，记录会出现在这里。没有笔记也算一次学习。</p>';const old=state.artifacts.filter(a=>!a.sessionId&&(!q||(a.text+' '+a.materialTitle).toLowerCase().includes(q)));$('recordList').innerHTML+=old.map(a=>`<article class="core-row"><h2>${esc(a.materialTitle)}</h2><p class="core-meta">${esc(a.date)} · 旧版笔记（保留原记录）</p><p>${esc(a.text)}</p></article>`).join('')}
function reviewSession(id){const r=state.sessions.find(s=>s.id===id);if(!state.reviews.some(x=>x.sessionId===id))state.reviews.push({id:uid(),sessionId:id,text:r.note,source:[r.title,r.position].filter(Boolean).join(' · '),level:0,next:dateAdd(1)});coreSave();renderAll();$('recordList').insertAdjacentHTML('afterbegin','<p class="notice" role="status">已加入复习，下次将在明天出现。</p>')}
function exportCoreMarkdown(){download('deutsch-os-records.md',state.sessions.filter(r=>r.status==='completed').map(r=>`# ${r.title}\n\n${r.date} · ${r.minutes} 分钟\n\n位置：${r.position}\n\n重点：${r.focus.join('、')}\n\n感受：${r.confidence}\n\n${r.note}\n\n${coreSource(r.sourceId)?.url||''}`).concat(state.artifacts.filter(a=>!a.sessionId).map(a=>`# ${a.materialTitle}\n\n${a.date}\n\n${a.text}\n\n${a.url||''}`)).join('\n\n---\n\n'),'text/markdown')}
renderAll=function(){const recent=[...state.sessions].filter(s=>s.status!=='planned'&&s.status!=='cancelled').sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));const last=recent[0];$('today').innerHTML=`<p class="eyebrow">${new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',weekday:'long'})}</p><h1 class="headline">从这里接着学</h1><div class="core-actions"><button class="primary" onclick="startSession()">直接开始学习</button><button class="secondary" onclick="addSource()">添加学习来源</button></div>${last?`<div class="card"><h2>继续上次 · ${esc(last.title)}</h2><p>${esc(last.position||'上次的位置尚未填写')}</p><button class="secondary" onclick="${last.status==='active'?`openSession('${last.id}')`:`startSession(${last.sourceId?`'${last.sourceId}'`:'null'})`}">继续学习</button></div>`:'<p class="sub">可以先添加一篇文章，也可以直接记录一次自由学习。</p>'}<div class="section-head"><h2>最近记录</h2><button class="ghost" onclick="showPage('notes')">全部记录</button></div>${recent.filter(r=>r.status==='completed').slice(0,3).map(r=>`<div class="core-row"><button class="ghost" onclick="openSession('${r.id}')">${esc(r.title)}</button><p class="core-meta">${esc(r.date)} · ${esc(r.position)} · ${r.minutes} 分钟</p></div>`).join('')}<div class="core-actions"><button class="ghost" onclick="showPage('review')">待复习 ${dueReviews().length} 条</button><button class="ghost" onclick="showPage('plan')">查看学习计划</button></div>`;renderSources();renderRecords();renderReview();renderPlan();fillSettings()};
renderPlan=function(){const planned=state.sessions.filter(r=>r.status==='planned');$('plan').innerHTML='<h1 class="headline">保留的学习计划</h1><p class="sub">旧任务都在这里。选择一项就能继续学习并留下记录。</p>'+planned.map(r=>`<div class="core-row"><h2>${esc(r.title)}</h2><p class="core-meta">原计划日期 ${esc(r.date)} · ${r.minutes} 分钟</p><button class="secondary" onclick="resumePlanned('${r.id}')">开始这次学习</button></div>`).join('')+(planned.length?'':'<p class="empty">没有尚未开始的旧任务。</p>')};
function resumePlanned(id){const r=state.sessions.find(s=>s.id===id);r.plannedDate=r.date;r.date=todayKey();r.status='active';r.updatedAt=Date.now();coreSave();openSession(id)}
document.querySelector('#settingsForm').onsubmit=e=>{e.preventDefault();state.settings=Object.fromEntries(new FormData(e.target));coreSave();};
document.querySelector('#settings .sub').textContent='学习偏好与本地数据备份。数据保存在当前浏览器，请定期导出。';
document.querySelector('#settingsForm .primary').textContent='保存偏好';
// Restored planner uses the same sessions/records as free learning. Legacy
// tasks/notes remain untouched; generating a plan never deletes old records.
function planDate(value,offset=0){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+offset);return localKey(d)}
function buildPlanDraft({start,days,minutes,sourceId},sources){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||planDate(start)!==start||!Number.isInteger(days)||days<1||days>7||!Number.isInteger(minutes)||minutes<5||minutes>180)throw Error('请填写有效日期、每周1–7天、每次5–180分钟。');
 if(sourceId&&!sources.some(s=>s.id===sourceId))throw Error('所选材料已不存在，请重新选择。');
 return Array.from({length:days},(_,i)=>{const source=sourceId?sources.find(s=>s.id===sourceId):sources.length?sources[i%sources.length]:null;return {date:planDate(start,Math.floor(i*7/days)),minutes,sourceId:source?.id||null,title:source?'学习 · '+source.title:'自由学习',sourceTitle:source?.title||'',sourceURL:source?.url||''};});
}
function appendPlanDraft(sessions,draft,idFactory){
 let added=0;for(const item of draft){if(sessions.some(s=>s.planSlot===item.date&&s.status!=='cancelled'))continue;sessions.push({...item,id:idFactory(),planSlot:item.date,plannedDate:item.date,plannedMinutes:item.minutes,status:'planned',focus:[],position:'',confidence:'刚接触',note:'',updatedAt:Date.now()});added++;}return added;
}
let planDraft=[],planMessage='';
let planNewSourceId=null;
function updatePlanSourceFields(){planDraft=[];planNewSourceId=null;$('confirmPlan').hidden=true;const adding=$('planSource').value==='@new';for(const suffix of ['Title','URL']){$('newPlan'+suffix+'Wrap').hidden=!adding;$('newPlan'+suffix).required=adding;}}
function resolvePlanSource(){
 const mode=$('planSource').value;
 if(mode==='@builtins')return {id:'',sources:builtinPlanSources};
 if(mode==='@free')return {id:'',sources:[]};
 if(mode==='@saved'){if(!state.sources.length)throw Error('还没有保存的材料，请选择内置资源或添加自己的网址。');return {id:'',sources:state.sources};}
 if(mode==='@new'){const title=$('newPlanTitle').value.trim(),url=safeURL($('newPlanURL').value);if(!title||!url)throw Error('请填写材料名称和有效的 http/https 网址。');if(!planNewSourceId)planNewSourceId=uid();return {id:'',sources:[{id:planNewSourceId,title,url,type:'教材',text:'',position:''}]};}
 return {id:mode,sources:[...builtinPlanSources,...state.sources]};
}
function planMonday(date){const day=new Date(date+'T12:00:00').getDay();return planDate(date,-((day+6)%7));}
let planWeekStart=planMonday(todayKey()),planSelectedDay=todayKey(),planView='week';
function displayPlanDate(value){const d=new Date(value+'T12:00:00');return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'}).format(d);}
const requestedPlanDate=new URLSearchParams(location.search).get('date');
if(requestedPlanDate&&/^\d{4}-\d{2}-\d{2}$/.test(requestedPlanDate)&&planDate(requestedPlanDate)===requestedPlanDate){planSelectedDay=requestedPlanDate;planWeekStart=planMonday(requestedPlanDate);}

function movePlanWeek(offset){planWeekStart=offset===0?planMonday(todayKey()):planDate(planWeekStart,offset*7);planSelectedDay=offset===0?todayKey():planWeekStart;renderPlan();}
function selectPlanDay(date){planSelectedDay=date;renderPlan();}
function switchPlanView(view){planView=view;renderPlan();}
const weekStyle=document.createElement('style');weekStyle.textContent=`.plan-week-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px}.plan-day{min-width:0;padding:12px;border:1px solid var(--line);border-radius:12px}.plan-day h2{font-size:15px}.plan-day .core-row h2{font-size:14px;overflow-wrap:anywhere}.plan-day .core-actions{gap:6px}.plan-day .core-actions>*{padding:8px;font-size:12px;min-height:44px;white-space:normal}.plan-day .core-row{padding:12px 0}.plan-day.selected-day{border-color:var(--ink)}.plan-mobile-days{display:none}.plan-view-tools{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.plan-view-tools button{min-height:44px}@media(max-width:1000px){.plan-week-grid{display:block}.plan-day{display:none}.plan-day.selected-day{display:block}.plan-mobile-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px;margin-bottom:12px}.plan-mobile-days button{min-width:0;min-height:48px;padding:4px;font-size:12px;border-radius:8px}.plan-mobile-days button[aria-pressed=true]{background:var(--ink);color:white}}`;document.head.append(weekStyle);
function planSourceOptions(){return '<option value="@builtins">使用内置德语资源（自动带出标题和链接）</option><option value="@saved">轮换我保存的材料</option><option value="@new">添加自己的网址</option><option value="@free">自由学习（不关联网站）</option><optgroup label="指定内置资源">'+builtinPlanSources.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')+'</optgroup><optgroup label="我保存的材料">'+state.sources.map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')+'</optgroup>';}
function openPlanBuilder(){persistSession();activeSessionId=null;planDraft=[];$('modalContent').innerHTML=`<h2>自动安排一周</h2><p class="sub">按可用时间安排，从开始日期起7天内均匀分布；不调用 AI，不删除旧任务。</p><form onsubmit="previewPlan(event)" oninput="planDraft=[];document.getElementById('confirmPlan').hidden=true;"><div class="form-grid"><label>开始日期<input id="planStart" type="date" required value="${todayKey()}"></label><label>每周学习几天<input id="planDays" type="number" min="1" max="7" required value="${Number(state.settings.days)||4}"></label><label>每次多少分钟<input id="planMinutes" type="number" min="5" max="180" required value="${Number(state.settings.minutes)||20}"></label><label>学习材料<select id="planSource" onchange="updatePlanSourceFields()">${planSourceOptions()}</select></label><label class="full" id="newPlanTitleWrap" hidden>材料名称<input id="newPlanTitle" maxlength="200"></label><label class="full" id="newPlanURLWrap" hidden>材料网址<input id="newPlanURL" type="url" placeholder="https://"></label></div><p>内置资源链接到课程或网站入口，不是自动定位到某一课。材料可以在每条任务中更换；先排一周，不承诺自动完成整本教材。</p><button class="primary">预览计划</button><div id="planPreview" aria-live="polite"></div><div class="modal-foot"><button type="button" class="ghost" onclick="closeModal()">取消</button><button id="confirmPlan" type="button" class="primary" hidden onclick="confirmWeeklyPlan()">确认加入计划</button></div></form>`;openModal();}
function previewPlan(e){e.preventDefault();try{planDraft=buildPlanDraft({start:$('planStart').value,days:Number($('planDays').value),minutes:Number($('planMinutes').value),sourceId:resolvePlanSource().id},resolvePlanSource().sources);$('planPreview').innerHTML=planDraft.map(t=>`<p>${esc(displayPlanDate(t.date))} · ${esc(t.title)} · ${t.minutes}分钟${state.sessions.some(s=>s.planSlot===t.date&&s.status!=='cancelled')?'（已有自动计划，将跳过）':''}</p>`).join('');$('confirmPlan').hidden=false;}catch(e){planDraft=[];$('confirmPlan').hidden=true;$('planPreview').textContent=e.message;}}
function confirmWeeklyPlan(){if(!planDraft.length)return;if($('planSource')?.value==='@new'){const selected=resolvePlanSource().sources[0];if(!state.sources.some(s=>s.id===selected.id))state.sources.push(selected);}const added=appendPlanDraft(state.sessions,planDraft,uid);state.settings.days=String($('planDays').value);state.settings.minutes=String($('planMinutes').value);coreSave();planMessage=added?`已加入 ${added} 条计划，已有计划及学习记录保持不变。`:'这些日期已有自动计划，未重复添加。';planDraft=[];closeModal();showPage('plan');}
function planRow(r){const source=coreSource(r.sourceId),url=safeURL(source?.url||r.sourceURL);const finished=r.status==='completed';return `<article class="core-row"><h2>${esc(r.title)}</h2><p class="core-meta">${esc(displayPlanDate(r.plannedDate||r.date))} · ${r.plannedMinutes||r.minutes} 分钟 · ${finished?'已完成':r.status==='active'?'进行中':r.date<todayKey()?'已过期，可顺延':'待学习'}</p><div class="core-actions"><button class="primary" onclick="resumePlanned('${r.id}')">${finished?'查看学习记录':r.status==='active'?'继续学习 / 记录':'开始学习 / 记录'}</button>${url?`<a class="secondary" href="${esc(url)}" target="_blank" rel="noopener">打开学习网站 ↗</a>`:''}${r.status==='planned'?`<button class="ghost" onclick="editPlanTask('${r.id}')">改期 / 时长 / 材料</button>${r.date<todayKey()?`<button class="ghost" onclick="postponePlan('${r.id}')">顺延到今天</button>`:''}`:''}</div></article>`}
renderPlan=function(){
 const rows=state.sessions.filter(r=>(r.status==='planned'||r.plannedDate||r.planSlot)&&r.status!=='cancelled'),pending=rows.filter(r=>r.status!=='completed').sort((a,b)=>a.date.localeCompare(b.date)),done=rows.filter(r=>r.status==='completed');
 const dates=Array.from({length:7},(_,i)=>planDate(planWeekStart,i)),labels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
 const calendar='<div class="plan-mobile-days">'+dates.map((date,i)=>`<button aria-pressed="${date===planSelectedDay}" onclick="selectPlanDay('${date}')">${labels[i]}<br>${date.slice(8)}</button>`).join('')+'</div><div class="plan-week-grid">'+dates.map((date,i)=>{const tasks=rows.filter(r=>(r.plannedDate||r.date)===date);return `<section class="plan-day ${date===planSelectedDay?'selected-day':''}"><h2>${labels[i]} · ${date.slice(5)}${date===todayKey()?' 今天':''}</h2>${tasks.map(planRow).join('')||'<p class="core-meta">暂无安排</p>'}</section>`;}).join('')+'</div>';
 $('plan').innerHTML=`<h1 class="headline">学习计划</h1><p class="sub">安排学习时间，打开网站，学完留下记录。原有任务保持不变。</p><div class="core-actions"><button class="primary" onclick="openPlanBuilder()">自动安排一周</button><button class="secondary" onclick="editPlanTask()">＋ 手动安排</button><button class="ghost" onclick="addPlanSource()">添加材料链接</button></div><p role="status">${esc(planMessage)}</p><div class="plan-view-tools"><button class="${planView==='week'?'primary':'ghost'}" onclick="switchPlanView('week')">周计划</button><button class="${planView==='list'?'primary':'ghost'}" onclick="switchPlanView('list')">全部任务列表</button></div>${planView==='week'?`<div class="plan-view-tools"><button class="ghost" onclick="movePlanWeek(-1)">← 上一周</button><button class="secondary" onclick="movePlanWeek(0)">本周</button><button class="ghost" onclick="movePlanWeek(1)">下一周 →</button><span>${displayPlanDate(planWeekStart)} — ${displayPlanDate(dates[6])}</span></div>${calendar}`:`<div class="card">${pending.map(planRow).join('')||'<p class="empty">没有待学习的任务。</p>'}</div>${done.length?`<details><summary>已完成 ${done.length} 项</summary>${done.map(planRow).join('')}</details>`:''}`}<p class="core-hint">计划和学习记录仍保存在当前浏览器，请定期导出。查看其他日期的任务可切换周，或打开全部任务列表。</p>`;
};
resumePlanned=function(id){const r=state.sessions.find(s=>s.id===id);if(!r)return;if(r.status==='planned'){r.plannedDate=r.plannedDate||r.date;r.plannedMinutes=r.plannedMinutes||r.minutes;r.date=todayKey();r.status='active';r.updatedAt=Date.now();coreSave();}openSession(id);};
function editPlanTask(id=''){persistSession();activeSessionId=null;const r=id?state.sessions.find(s=>s.id===id):{date:todayKey(),minutes:20,title:'',sourceId:null};if(!r||id&&r.status!=='planned')return;$('modalContent').innerHTML=`<h2>${id?'调整任务':'手动安排任务'}</h2><form onsubmit="savePlanTask(event,'${id}')"><div class="form-grid"><label>日期<input id="editPlanDate" type="date" required value="${esc(r.date)}"></label><label>预计分钟<input id="editPlanMinutes" type="number" min="5" max="180" required value="${r.minutes}"></label><label class="full">任务名称<input id="editPlanTitle" maxlength="200" value="${esc(r.title)}" placeholder="留空使用材料名称"></label><label class="full">材料<select id="editPlanSource"><option value="">自由学习（不关联材料）</option>${[...builtinPlanSources,...state.sources].map(s=>`<option value="${esc(s.id)}" ${s.id===r.sourceId?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label></div><div class="modal-foot"><button type="button" class="ghost" onclick="closeModal()">取消</button>${id?`<button type="button" class="ghost" onclick="cancelPlanTask('${id}')">移除这条待办</button>`:''}<button class="primary">保存任务</button></div></form>`;openModal();}
function savePlanTask(e,id){e.preventDefault();const source=coreSource($('editPlanSource').value),date=$('editPlanDate').value,minutes=Number($('editPlanMinutes').value);if(planDate(date)!==date||minutes<5||minutes>180||!Number.isInteger(minutes))return;let r=id?state.sessions.find(s=>s.id===id):{id:uid(),status:'planned',focus:[],position:'',confidence:'刚接触',note:''};if(!r||r.status!=='planned')return;Object.assign(r,{date,plannedDate:date,minutes,plannedMinutes:minutes,title:$('editPlanTitle').value.trim()||source?.title||'自由学习',sourceId:source?.id||null,sourceTitle:source?.title||'',sourceURL:source?.url||'',updatedAt:Date.now()});if(r.planSlot)r.planSlot=date;if(!id)state.sessions.push(r);coreSave();closeModal();}
function cancelPlanTask(id){if(!confirm('从待办中移除这条任务？不会删除其他记录。'))return;const r=state.sessions.find(s=>s.id===id);if(r?.status!=='planned')return;r.status='cancelled';coreSave();closeModal();}
function postponePlan(id){const r=state.sessions.find(s=>s.id===id);if(r?.status!=='planned')return;r.date=todayKey();r.plannedDate=r.date;if(r.planSlot)r.planSlot=r.date;coreSave();renderAll();}
function addPlanSource(){persistSession();activeSessionId=null;$('modalContent').innerHTML=`<h2>添加计划材料</h2><form onsubmit="savePlanSource(event)"><div class="form-grid"><label class="full">材料名称<input id="planSourceTitle" required maxlength="200" placeholder="如：Nicos Weg A1 第3课"></label><label class="full">网页链接<input id="planSourceURL" type="url" required placeholder="https://"></label></div><p>只保存链接，不抓取网页，不调用 API。</p><div class="modal-foot"><button type="button" class="ghost" onclick="closeModal()">取消</button><button class="primary">保存材料</button></div></form>`;openModal();}
function savePlanSource(e){e.preventDefault();const url=safeURL($('planSourceURL').value);if(!url){$('planSourceURL').setCustomValidity('请填写 http 或 https 链接');$('planSourceURL').reportValidity();$('planSourceURL').oninput=()=> $('planSourceURL').setCustomValidity('');return;}const title=$('planSourceTitle').value.trim();if(!title)return;state.sources.unshift({id:uid(),title,url,type:'教材',text:'',position:''});coreSave();closeModal();}
document.querySelectorAll('.nav button').forEach(b=>{if(b.textContent==='旧版计划')b.textContent='学习计划';});
const mobilePlan=document.createElement('button');mobilePlan.textContent='计划';mobilePlan.dataset.page='plan';mobilePlan.onclick=()=>showPage('plan');document.querySelector('.bottom-nav').append(mobilePlan);
const previousShowPage=showPage;showPage=function(name){previousShowPage(name);history.replaceState(null,'','#'+name);};
renderAll();
if(['today','plan','materials','notes','review','settings'].includes(location.hash.slice(1)))showPage(location.hash.slice(1));
if(new URLSearchParams(location.search).get('add')==='source')addSource();
